//! Demo video (SPEC §12.3): bundled H.264 clips replayed in real time through
//! the same stream manager and egress as real cameras.
//!
//! The clips (`assets/demo/`, generated by `scripts/gen-demo-clips.ps1`) are
//! embedded in the binary and parsed once. Timestamps keep increasing across
//! loops, and every loop starts with a keyframe, so a looping clip looks like a
//! continuous live stream to viewers.

use std::sync::OnceLock;
use std::time::Duration;

use async_trait::async_trait;
use tokio::time::{Instant, MissedTickBehavior};
use tokio_util::sync::CancellationToken;

use super::h264::{self, AccessUnit};
use super::media::{MediaEvent, MediaFrame, MediaSource, VideoParams, TIMESCALE};
use crate::providers::{ProviderError, VideoCodec};

/// The clip patterns, in the order cameras are assigned to them.
pub const PATTERNS: [&str; 4] = ["testsrc2", "mandelbrot", "gradients", "bars"];

macro_rules! clip_bytes {
    ($name:literal) => {
        include_bytes!(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../assets/demo/",
            $name
        ))
    };
}

/// (pattern, profile, bytes, width, height, fps); mirrors `assets/demo/clips.json`.
type RawClip = (&'static str, &'static str, &'static [u8], u32, u32, u32);

const RAW: [RawClip; 8] = [
    (
        "testsrc2",
        "main",
        clip_bytes!("testsrc2-main.h264"),
        1280,
        720,
        25,
    ),
    (
        "testsrc2",
        "grid",
        clip_bytes!("testsrc2-grid.h264"),
        640,
        360,
        15,
    ),
    (
        "mandelbrot",
        "main",
        clip_bytes!("mandelbrot-main.h264"),
        1280,
        720,
        25,
    ),
    (
        "mandelbrot",
        "grid",
        clip_bytes!("mandelbrot-grid.h264"),
        640,
        360,
        15,
    ),
    (
        "gradients",
        "main",
        clip_bytes!("gradients-main.h264"),
        1280,
        720,
        25,
    ),
    (
        "gradients",
        "grid",
        clip_bytes!("gradients-grid.h264"),
        640,
        360,
        15,
    ),
    ("bars", "main", clip_bytes!("bars-main.h264"), 1280, 720, 25),
    ("bars", "grid", clip_bytes!("bars-grid.h264"), 640, 360, 15),
];

#[derive(Debug)]
pub struct DemoClip {
    pub pattern: &'static str,
    pub profile: &'static str,
    pub params: VideoParams,
    pub units: Vec<AccessUnit>,
    pub fps: u32,
}

fn clips() -> &'static [DemoClip] {
    static CLIPS: OnceLock<Vec<DemoClip>> = OnceLock::new();
    CLIPS.get_or_init(|| {
        RAW.iter()
            .filter_map(|&(pattern, profile, bytes, width, height, fps)| {
                // The clips are generated and committed by us; a parse failure
                // is a build mistake, so skip the clip rather than crash.
                let es = match h264::parse_annexb(bytes) {
                    Ok(es) => es,
                    Err(e) => {
                        tracing::error!(pattern, profile, error = %e, "bundled demo clip is invalid");
                        return None;
                    }
                };
                Some(DemoClip {
                    pattern,
                    profile,
                    params: VideoParams {
                        codec: VideoCodec::H264,
                        rfc6381: h264::rfc6381(&es.sps),
                        width,
                        height,
                        sample_entry: h264::avc1_sample_entry(width, height, &es.sps, &es.pps).into(),
                    },
                    units: es.units,
                    fps,
                })
            })
            .collect()
    })
}

/// The clip for a pattern index and a profile name (`grid`, or anything else
/// for the full-size clip).
pub fn clip(pattern_index: usize, profile: &str) -> Option<&'static DemoClip> {
    let pattern = PATTERNS[pattern_index % PATTERNS.len()];
    let wanted = if profile == "grid" { "grid" } else { "main" };
    clips()
        .iter()
        .find(|c| c.pattern == pattern && c.profile == wanted)
}

/// Replays a clip in real time, forever (until dropped or cancelled).
pub struct DemoMediaSource {
    clip: &'static DemoClip,
    next_index: u64,
    sent_params: bool,
    frame_duration: i64,
    ticker: tokio::time::Interval,
    cancel: CancellationToken,
}

impl DemoMediaSource {
    pub fn new(clip: &'static DemoClip, cancel: CancellationToken) -> Self {
        let period = Duration::from_secs(1) / clip.fps.max(1);
        let mut ticker = tokio::time::interval_at(Instant::now() + period, period);
        // If the consumer stalls, don't burst frames to catch up: real cameras
        // don't either.
        ticker.set_missed_tick_behavior(MissedTickBehavior::Delay);
        Self {
            clip,
            next_index: 0,
            sent_params: false,
            frame_duration: i64::from(TIMESCALE / clip.fps.max(1)),
            ticker,
            cancel,
        }
    }
}

#[async_trait]
impl MediaSource for DemoMediaSource {
    async fn next(&mut self) -> Result<Option<MediaEvent>, ProviderError> {
        if !self.sent_params {
            self.sent_params = true;
            return Ok(Some(MediaEvent::Params(self.clip.params.clone())));
        }
        if self.next_index > 0 {
            tokio::select! {
                () = self.cancel.cancelled() => return Ok(None),
                _ = self.ticker.tick() => {}
            }
        }
        let n = self.clip.units.len() as u64;
        let unit = &self.clip.units[(self.next_index % n) as usize];
        let ts = i64::try_from(self.next_index).unwrap_or(i64::MAX) * self.frame_duration;
        self.next_index += 1;
        Ok(Some(MediaEvent::Frame(MediaFrame {
            pts: ts,
            dts: ts,
            keyframe: unit.keyframe,
            data: unit.avc.clone(),
        })))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn all_clips_parse_and_start_with_a_keyframe() {
        assert_eq!(clips().len(), RAW.len());
        for c in clips() {
            assert!(c.units[0].keyframe, "{} {}", c.pattern, c.profile);
            assert!(c.params.rfc6381.starts_with("avc1."));
        }
        assert_eq!(clip(1, "grid").unwrap().params.width, 640);
        assert_eq!(
            clip(5, "main").unwrap().pattern,
            "mandelbrot",
            "index wraps"
        );
    }

    #[tokio::test(start_paused = true)]
    async fn replays_in_real_time_with_monotonic_timestamps_across_loops() {
        let clip = clip(0, "grid").unwrap();
        let n = clip.units.len();
        let mut src = DemoMediaSource::new(clip, CancellationToken::new());
        assert!(matches!(
            src.next().await.unwrap(),
            Some(MediaEvent::Params(_))
        ));

        let start = Instant::now();
        let mut last = -1;
        let mut keyframes_at = Vec::new();
        for i in 0..(n + 5) {
            let Some(MediaEvent::Frame(f)) = src.next().await.unwrap() else {
                panic!()
            };
            assert!(f.pts > last, "timestamps increase across the loop");
            last = f.pts;
            if f.keyframe {
                keyframes_at.push(i);
            }
        }
        assert!(
            keyframes_at.contains(&0) && keyframes_at.contains(&n),
            "{keyframes_at:?}"
        );
        // n + 5 frames at 15 fps ≈ (n + 4) / 15 seconds of wall clock.
        let expected = Duration::from_secs(1) / 15 * u32::try_from(n + 4).unwrap();
        assert!(
            start.elapsed() >= expected,
            "{:?} < {expected:?}",
            start.elapsed()
        );
    }

    #[tokio::test(start_paused = true)]
    async fn cancel_ends_the_source() {
        let cancel = CancellationToken::new();
        let mut src = DemoMediaSource::new(clip(0, "main").unwrap(), cancel.clone());
        src.next().await.unwrap(); // params
        src.next().await.unwrap(); // first frame
        cancel.cancel();
        assert!(src.next().await.unwrap().is_none());
    }
}
